extern "C" int strlen(const char *);

typedef float vm_num_t;

class stringx;

class string_buf
{
  friend stringx operator+(const stringx &, const char *);
  friend stringx operator+(const stringx &, const stringx &);

  unsigned long long *data;
  int ref_count;
  int char_length;
};

class stringx
{
  char *chars;
  string_buf *my_buf;

public:
  stringx();
  stringx(const stringx &);
  ~stringx();
  void append(const char *, int = -1);
  void append(const stringx &);
  void make_room(int);

  friend stringx operator+(const stringx &, const char *);
  friend stringx operator+(const stringx &, const stringx &);
};

inline stringx operator+(const stringx &lhs, const char *rhs)
{
  stringx foo;
  int len = strlen(rhs);
  foo.make_room(lhs.my_buf->char_length + len);
  foo.append(lhs);
  foo.append(rhs, len);
  return foo;
}

inline stringx operator+(const stringx &lhs, const stringx &rhs)
{
  stringx foo;
  foo.make_room(lhs.my_buf->char_length + rhs.my_buf->char_length);
  foo.append(lhs);
  foo.append(rhs);
  return foo;
}

namespace script_object
{
class instance
{
  stringx name;

public:
  const stringx &get_name() const { return name; }
};
}

class vm_executable
{
  void *owner;
  stringx name;
  stringx fullname;

public:
  const stringx &get_fullname() const { return fullname; }
};

class vm_thread
{
  script_object::instance *inst;
  const vm_executable *ex;

public:
  script_object::instance *get_instance() const { return inst; }
  const vm_executable *get_executable() const { return ex; }
};

class vm_stack
{
public:
  int salloc;
  char *buffer;
  char *SP;

private:
  vm_thread *my_thread;

public:
  vm_thread *get_thread() const { return my_thread; }
  bool push(const char *, int);
};

class script_library_class
{
public:
  class function
  {
  public:
    enum entry_t
    {
      FIRST_ENTRY,
      RECALL_ENTRY
    };

    virtual bool operator()(vm_stack &stack, entry_t entry) { return true; }
  };
};

void error(const stringx &);

class slf_get_detail_level_t : public script_library_class::function
{
public:
  virtual bool operator()(vm_stack &stack, entry_t entry)
  {
#ifdef TARGET_PC
    vm_num_t result = 0;
#else
    vm_num_t result = 2;
#endif
    if (!stack.push((char *)&result, sizeof(result)))
      error(stack.get_thread()->get_instance()->get_name() + ": stack overflow in " + stack.get_thread()->get_executable()->get_fullname());
    return true;
  }
};
